/*
 * Reggaeton El Real - Security Fase 5
 * TinyMCE 4.7.13 was removed. This compatibility shim keeps the legacy
 * admin.php calls harmless while native <textarea> controls are used.
 * It also normalizes HTML entities left behind by the retired editor.
 */
(function (global) {
    "use strict";

    if (!global || !global.document) {
        return;
    }

    var namedEntities = {
        amp: "&",
        apos: "'",
        quot: '"',
        lt: "<",
        gt: ">",
        nbsp: "\u00a0",
        aacute: "á",
        eacute: "é",
        iacute: "í",
        oacute: "ó",
        uacute: "ú",
        ntilde: "ñ",
        uuml: "ü",
        Aacute: "Á",
        Eacute: "É",
        Iacute: "Í",
        Oacute: "Ó",
        Uacute: "Ú",
        Ntilde: "Ñ",
        Uuml: "Ü",
        iquest: "¿",
        iexcl: "¡"
    };

    function decodeEntity(match, token) {
        var codePoint;

        if (token.charAt(0) === "#") {
            if (token.charAt(1).toLowerCase() === "x") {
                codePoint = parseInt(token.slice(2), 16);
            } else {
                codePoint = parseInt(token.slice(1), 10);
            }

            if (
                !Number.isFinite(codePoint) ||
                codePoint < 0 ||
                codePoint > 0x10ffff ||
                (codePoint >= 0xd800 && codePoint <= 0xdfff)
            ) {
                return match;
            }

            return String.fromCodePoint(codePoint);
        }

        return Object.prototype.hasOwnProperty.call(namedEntities, token)
            ? namedEntities[token]
            : match;
    }

    function decodeLegacyEntities(value) {
        var normalized = String(value || "");
        var previous;
        var passes = 0;

        do {
            previous = normalized;
            normalized = normalized.replace(
                /&(#x[0-9a-f]+|#\d+|[a-z]+);/gi,
                decodeEntity
            );
            passes++;
        } while (normalized !== previous && passes < 2);

        return normalized;
    }

    function normalizeTextareas() {
        var textareas = global.document.querySelectorAll("textarea.js-richtext");

        Array.prototype.forEach.call(textareas, function (textarea) {
            textarea.value = decodeLegacyEntities(textarea.value);
        });
    }

    global.tinymce = {
        init: function () {
            if (global.document.readyState === "loading") {
                global.document.addEventListener(
                    "DOMContentLoaded",
                    normalizeTextareas,
                    { once: true }
                );
            } else {
                normalizeTextareas();
            }

            return [];
        },
        triggerSave: function () {
            normalizeTextareas();
            return undefined;
        }
    };
})(typeof window !== "undefined" ? window : this);
